// === Récupération de l'item courant (réponse Claude) ===
const item = $input.item.json;

// === 1. Extraction du texte de la réponse ===
const rawText = item.content?.[0]?.text || '';

if (!rawText) {
  // Réponse Claude vide : on log et on rejette l'item
  return {
    json: {
      classification_error: true,
      error_reason: 'empty_response',
      claude_message_id: item.id || null,
      raw_response: JSON.stringify(item).substring(0, 500)
    }
  };
}

// === 2. Reconstitution du JSON (le { initial a été préfillé côté assistant) ===
const fullJson = '{' + rawText;

// === 3. Parsing ===
let classification;
try {
  classification = JSON.parse(fullJson);
} catch (err) {
  return {
    json: {
      classification_error: true,
      error_reason: 'json_parse_failed',
      error_detail: err.message,
      claude_message_id: item.id || null,
      raw_text: fullJson.substring(0, 500)
    }
  };
}

// === 4. Validation des champs (référentiels fermés) ===
const VALID_THEMATIQUES = ['rgpd', 'cyber', 'vulnerabilites', 'ai_act', 'nis2', 'dora', 'iso_27001', 'iso_42001', 'incident', 'sanction', 'doctrine', 'autre'];
const VALID_CRITICITES = ['faible', 'moyenne', 'elevee', 'critique'];

const errors = [];

// Thématiques : doivent toutes être dans le référentiel
if (!Array.isArray(classification.thematiques) || classification.thematiques.length === 0) {
  errors.push('thematiques manquantes ou non-tableau');
} else {
  const invalidThematiques = classification.thematiques.filter(t => !VALID_THEMATIQUES.includes(t));
  if (invalidThematiques.length > 0) {
    errors.push(`thematiques invalides: ${invalidThematiques.join(', ')}`);
  }
}

// Criticité
if (!VALID_CRITICITES.includes(classification.criticite)) {
  errors.push(`criticite invalide: ${classification.criticite}`);
}

// Score de pertinence
const score = parseFloat(classification.score_pertinence);
if (isNaN(score) || score < 0 || score > 1) {
  errors.push(`score_pertinence invalide: ${classification.score_pertinence}`);
}

// Justification
if (typeof classification.justification !== 'string' || classification.justification.length < 10) {
  errors.push('justification trop courte ou manquante');
}

// === 5. Si erreurs de validation, on flag mais on retourne quand même ===
if (errors.length > 0) {
  return {
    json: {
      classification_error: true,
      error_reason: 'validation_failed',
      error_detail: errors.join(' | '),
      raw_classification: classification,
      claude_message_id: item.id || null
    }
  };
}

// === 6. Récupération des données de l'article original (depuis le nœud 1) ===
// On utilise $('1. Get articles non classifiés') pour aller chercher les données amont
const articleData = $('1. Get articles non classifiés').item.json;

// === 7. Construction de l'objet final pour l'INSERT ===
return {
  json: {
    // Lien vers l'article
    article_id: articleData.id,

    // Champs de classification (table classifications)
    thematiques: classification.thematiques,
    criticite: classification.criticite,
    score_pertinence: score,
    justification: classification.justification,

    // Tracking technique (audit + coût)
    modele_utilise: item.model || 'claude-haiku-4-5',
    tokens_input: item.usage?.input_tokens || 0,
    tokens_output: item.usage?.output_tokens || 0,
    cout_euros: ((item.usage?.input_tokens || 0) / 1000000 * 1 + (item.usage?.output_tokens || 0) / 1000000 * 5) * 0.93, // approximation USD→EUR
    claude_message_id: item.id,

    // Pour debug si besoin
    classification_error: false
  }
};
